import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getForumTopic, getTopicReplies, createTopicReply } from '../../api';

export default function TopicView() {
  const { topicId } = useParams();
  const [topic, setTopic] = useState(null);
  const [replies, setReplies] = useState([]);
  const [newReply, setNewReply] = useState('');
  const [username, setUsername] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    loadTopicData();
    getUserInfo();
  }, [topicId]);

  const loadTopicData = async () => {
    try {
      const [topicData, repliesData] = await Promise.all([
        getForumTopic(topicId),
        getTopicReplies(topicId)
      ]);
      setTopic(topicData);
      setReplies(repliesData);
    } catch (error) {
      console.error('Error loading topic:', error);
    }
  };

  const getUserInfo = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch('http://localhost:8080/api/auth/profile', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (response.ok) {
        const data = await response.json();
        setUsername(data.username);
      }
    } catch (error) {
      console.error('Error getting user info:', error);
    }
  };

  const handleReply = async (e) => {
    e.preventDefault();
    try {
      await createTopicReply({
        topicId,
        content: newReply,
        author: username
      });
      setNewReply('');
      loadTopicData();
    } catch (error) {
      console.error('Error creating reply:', error);
    }
  };

  if (!topic) return <div>Loading...</div>;

  return (
    <div className="topic-view">
      <div className="topic-header">
        <button onClick={() => navigate('/forums')} className="back-btn">← Back to Forums</button>
        <h1>{topic.title}</h1>
      </div>

      <div className="topic-content">
        <div className="original-post">
          <div className="post-header">
            <strong>{topic.author}</strong>
            <span>{new Date(topic.createdAt).toLocaleString()}</span>
          </div>
          <div className="post-content">{topic.content}</div>
        </div>

        <div className="replies-section">
          <h3>Replies ({replies.length})</h3>

          {replies.map(reply => (
            <div key={reply.id} className="reply">
              <div className="post-header">
                <strong>{reply.author}</strong>
                <span>{new Date(reply.createdAt).toLocaleString()}</span>
              </div>
              <div className="post-content">{reply.content}</div>
            </div>
          ))}

          <div className="reply-form">
            <h4>Add a Reply</h4>
            <form onSubmit={handleReply}>
              <textarea
                value={newReply}
                onChange={(e) => setNewReply(e.target.value)}
                placeholder="Write your reply..."
                required
              />
              <button type="submit">Post Reply</button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}
